//! A Bluetooth profile driver's two functions, after BeginIO and AbortIO:
//! what bluetooth.library calls a driver in DEVS:bluetooth/ with when it
//! offers it a service of a bonded device, and when it takes it back.
//! Every profile driver has them (sdk/devices/btprofile.zig); the base is
//! the driver's, io_Device of an open request.
//!
//! Generated by sdk/tools/fd2zig from sdk/fd/btprofile_lib.fd: change that file
//! and run `zig build fd`, not this one.

const libraries = @import("../libs/exec/libraries.zig");
const bluetooth = @import("../libs/bluetooth/bluetooth.zig");

/// The name to open it by (OpenLibrary, OpenDevice).
pub const NAME = "btprofile";

/// Each function's offset in the jump table (its LVO).
pub const LVO = struct {
    pub const BTProfileBind = libraries.lvo(6);
    pub const BTProfileUnbind = libraries.lvo(7);
};

/// Each function's type, by its name in LVO. The first argument is the
/// library's base.
pub const Fn = struct {
    pub const BTProfileBind = *const fn (*BTProfileBase, *bluetooth.BTBinding) callconv(.c) bool;
    pub const BTProfileUnbind = *const fn (*BTProfileBase, *bluetooth.BTBinding, u32) callconv(.c) void;
};

/// The library's base. Its methods are the library's functions, and
/// each calls through the jump table.
pub const BTProfileBase = opaque {
    /// The Library header at the base.
    pub fn lib(self: *BTProfileBase) *libraries.Library {
        return @ptrCast(@alignCast(self));
    }

    /// A service offered: true if the driver takes it - it has filled a
    /// unit, `binding.unit` saying which, and keeps `binding` until
    /// BTProfileUnbind - false if it declines and the next driver is asked.
    /// Called on the library's binder process, which serves nothing else
    /// meanwhile: the driver may call the library - read the service's
    /// record, add listeners, open channels - and wait for it.
    pub fn BTProfileBind(self: *BTProfileBase, binding: *bluetooth.BTBinding) bool {
        return libraries.call(self, LVO.BTProfileBind, Fn.BTProfileBind, .{binding});
    }

    /// The service is taken back - its controller gone, or its bond ended
    /// (BTPU_FORGET in `flags`, for the driver to tell the device first,
    /// while the link is there): its channels closed, its unit left without
    /// it, `binding` no longer the driver's. Called on the binder process.
    pub fn BTProfileUnbind(self: *BTProfileBase, binding: *bluetooth.BTBinding, flags: u32) void {
        return libraries.call(self, LVO.BTProfileUnbind, Fn.BTProfileUnbind, .{ binding, flags });
    }
};
